  function applyRegionRandomizedOutcomes(outcomes){
    if(!outcomes)return;
    const byId=id=>decisions.find(d=>d.id===id);
    byId('e15').options[1].money=outcomes.e15Money;
    byId('m15').options[2].growth=outcomes.m15Growth;
    byId('m20').options[0].growth=outcomes.m20Growth;
    byId('l04').options[2].growth=outcomes.l04Growth;
    byId('l08').options[1].growth=outcomes.l08Growth;
    byId('l16').options[0].growth=outcomes.l16Growth;
    byId('a09').options[2].growth=outcomes.a09Growth;
    byId('a12').options[0].growth=outcomes.a12Growth;
    byId('a15').options[2].growth=outcomes.a15Growth;
    byId('a19').options[2].growth=outcomes.a19Growth;
  }
  function refreshRegionRandomizedOutcomes(){
    const outcomes={e15Money:random()>.45?110:0,m15Growth:random()>.5?8:-8,m20Growth:random()>.4?16:-10,l04Growth:random()>.45?7:-10,l08Growth:random()>.5?12:-7,l16Growth:random()>.35?18:-12,a09Growth:random()>.5?9:-4,a12Growth:random()>.35?9:-9,a15Growth:random()>.5?4:-7,a19Growth:random()>.5?10:-9};
    state.regionRandomOutcomes=outcomes;
    applyRegionRandomizedOutcomes(outcomes);
  }

