  function pickBrand(international=false){return pick(international?internationalBrands:nationalBrands)}
  function brandForDecision(d){const useInternational=state.year>=9&&(state.staff.representation==='agency'||state.viewers>=10000)&&random()<.55;return pickBrand(useInternational)}
  function materializeBrandDecision(d){if(!brandDecisionIds.has(d.id))return d;const brand=brandForDecision(d);const opts=d.options.map(o=>({...o,text:(o.text||'').replace(/Buscar patrocinadores/g,`Buscar a ${brand} como patrocinador principal`).replace(/Reducir sponsors/g,`Reducir la presencia de ${brand}`).replace(/Mantener contratos actuales/g,`Mantener el acuerdo con ${brand}`).replace(/Aceptar todavía más campañas/g,`Dar todavía más espacio a ${brand}`)}));let title=d.title.replace(/BRANDNAME/g,brand);if(d.id==='e15')title=`${brand} aparece como tu primer sponsor pequeño`;if(d.id==='m02')title=`${brand} pide una propuesta`;if(d.id==='m16')title=`${brand} quiere decidir cómo hablas de su producto`;if(d.id==='a18')title=`${brand} te ofrece participar en una campaña con otros creadores`;let context=d.context;if(d.id==='e15')context=`${brand} ofrece poco dinero por una mención.`;return{...d,title,context,options:opts,brandName:brand};}

  function creatorTierIndex(viewers=state.viewers){if(viewers<26)return-1;return creatorPools.findIndex(p=>viewers>=p.min&&viewers<=p.max)}
  function firstCreatorTier(name){return creatorPools.findIndex(p=>p.primary.includes(name))}
  function creatorCandidates(idx){const out=[];for(let i=0;i<=idx;i++)for(const name of creatorPools[i].primary)if(!out.includes(name))out.push(name);return out}
  function pickCreator(exclude=[]){
    const idx=creatorTierIndex();if(idx<0)return null;let names=creatorCandidates(idx).filter(n=>!exclude.includes(n)),current=creatorPools[idx].primary.filter(n=>!exclude.includes(n));if(!names.length)return null;if(!current.length)current=names;
    const currentEach=100/current.length;
    const weights=names.map(name=>{const first=firstCreatorTier(name),distance=idx-first;let w;if(distance===0)w=currentEach;else if(name==='FeirlyGab'||(idx===creatorPools.length-1&&creatorLegends.has(name)))w=currentEach;else{const oldPoolBudget=35*Math.pow(.45,Math.max(0,distance-1));w=oldPoolBudget/creatorPools[first].primary.length;}if(name!=='FeirlyGab'&&state.cameos.includes(name))w*=.55;return Math.max(.03,w);});
    return weightedPick(names,weights);
  }
  function personalizeCreatorText(text,name){if(!text)return text;const n=name||pickCreator();if(!n)return text.replace(/XXXCREADORXXX/g,'otro creador');return text.replace(/XXXCREADORXXX/g,n).replace(/Un creador conocido/g,n).replace(/un creador conocido/g,n).replace(/Un creador venezolano/g,n).replace(/un creador venezolano/g,n).replace(/Un streamer parecido a ti/g,n).replace(/un streamer parecido a ti/g,n).replace(/Un streamer grande/g,n).replace(/un streamer grande/g,n).replace(/Una figura histórica del streaming hispano/g,n).replace(/una figura histórica del streaming hispano/g,n).replace(/Un streamer hispano histórico/g,n).replace(/un streamer hispano histórico/g,n);}
  function textNeedsCreator(text=''){return /XXXCREADORXXX|[Uu]n creador conocido|[Uu]n creador venezolano|[Uu]n streamer parecido a ti|[Uu]n streamer grande|[Uu]na figura histórica del streaming hispano|[Uu]n streamer hispano histórico/.test(text)}
  function materializeDecision(d){if(state.viewers<26||(!textNeedsCreator(d.title)&&!textNeedsCreator(d.context)))return{...d,creatorName:null};const name=pickCreator();return{...d,title:personalizeCreatorText(d.title,name),context:personalizeCreatorText(d.context,name),creatorName:name};}
  function eventPick(tier,exclude=[]){const available=(eventCatalog[tier]||[]).filter(e=>!state.usedEventNames.includes(e.name)&&!exclude.includes(e.name));if(!available.length)return null;const selected=pick(available),base=selected.name;const modality=selected.mode==='hybrid'?(random()<.5?'presencial':'online'):selected.mode;let venue=null,name=base;if(modality==='presencial'&&(tier==='small'||tier==='medium')){venue=pick(eventVenues);name=`${base} · ${venue}`;}return{name,base,venue,modality,configuredMode:selected.mode,external:externalEvents.has(base)};}
  function hasEventName(tier){return (eventCatalog[tier]||[]).some(e=>!state.usedEventNames.includes(e.name));}
  function eventModeLabel(e){if(!e?.modality)return'';return e.modality==='presencial'?'Presencial':'Online'}

  function expectedTechLevel(v=state.viewers){if(v>=5000)return 5;if(v>=3000)return 4;if(v>=1500)return 3;if(v>=500)return 2;if(v>=70)return 1;return 0;}
  function technicalGrowthFactor(){const need=expectedTechLevel(),pcGap=Math.max(0,need-state.upgrades.pc),audioGap=Math.max(0,need-state.upgrades.audio),cameraGap=Math.max(0,need-state.upgrades.camera);return Math.max(.26,Math.pow(.76,pcGap)*Math.pow(.95,audioGap)*Math.pow(.96,cameraGap));}
  function applyQualityPressure(){const need=expectedTechLevel();if(!need)return;const a=Math.max(0,need-state.upgrades.audio),c=Math.max(0,need-state.upgrades.camera),p=Math.max(0,need-state.upgrades.pc);if(a&&random()<Math.min(.65,.20*a)){state.community=clamp(state.community-1,0,100);state.signals.push('Parte del chat empieza a notar que el audio se queda atrás para el tamaño del canal.');}if(c&&random()<Math.min(.55,.16*c)){state.community=clamp(state.community-1,0,100);}if(p>=2)state.signals.push('El equipo principal empieza a sentirse pequeño para lo que intentas hacer.');}
  function expectedModerators(v=state.viewers){if(v<150)return 0;if(v<500)return 1;if(v<2000)return 2;if(v<5000)return 3;if(v<15000)return 4;return 5;}
  function applyModerationPressure(){const need=expectedModerators(),gap=Math.max(0,need-state.staff.mod);if(!gap)return;const loss=Math.max(1,Math.round(gap*(.8+random()*.55)));state.community=clamp(state.community-loss,0,100);state.hidden.risk+=gap*.18;if(gap>=2)state.signals.push('El chat creció más rápido que tu moderación. El ambiente empieza a deteriorarse y cada trimestre sin apoyo pesa más.');}
  function livingCost(){const v=state.viewers;let mult=1;if(v>=50000)mult=1.80;else if(v>=25000)mult=1.58;else if(v>=10000)mult=1.38;else if(v>=5000)mult=1.25;else if(v>=2000)mult=1.14;else if(v>=500)mult=1.06;return Math.round(state.location.living*mult);}
  function activeTemporaryViral(){return state.viralBoosts.reduce((sum,b)=>sum+Math.max(0,b.temporaryRemaining||0),0)}
  function consumeViralAudience(loss){let left=Math.max(0,Math.round(loss));if(!left)return 0;let consumed=0;for(const b of state.viralBoosts){if(left<=0)break;const available=Math.max(0,b.temporaryRemaining||0),take=Math.min(available,left);b.temporaryRemaining=available-take;left-=take;consumed+=take;}return consumed;}
  function decayViralBoosts(){let loss=0;for(const b of state.viralBoosts){if(b.stepsLeft<=0)continue;const d=b.stepsLeft===1?Math.max(0,b.temporaryRemaining||0):Math.min(Math.max(0,b.temporaryRemaining||0),b.decayPerQuarter);if(d>0){b.temporaryRemaining-=d;state.viewers=Math.max(0,state.viewers-d);loss+=d;}b.stepsLeft--;}state.viralBoosts=state.viralBoosts.filter(b=>b.stepsLeft>0&&(b.temporaryRemaining||0)>0);if(loss>0)state.signals.push('Parte del público temporal que llegó por un clip viral se fue diluyendo con el tiempo.');return loss;}
  function debtSeverity(){if(state.money>=0)return 0;const debt=Math.abs(state.money),scale=Math.max(450,state.viewers*.45);return clamp(debt/scale,0.5,4);}
  function debtOpportunityFactor(){const sev=debtSeverity();return sev?Math.max(.18,1-sev*.19):1;}
  function applyDebtPressure(){const sev=debtSeverity();if(!sev)return;const before=state.viewers;applyGrowth(-Math.round(1.5+sev*1.7));state.energy=clamp(state.energy-Math.round(2+sev*2),0,100);state.morale=clamp(state.morale-Math.round(3+sev*2.2),0,100);state.community=clamp(state.community-Math.max(1,Math.round(sev*.8)),0,100);state.hidden.risk+=sev*.35;if(state.staff.mod+state.staff.editor+state.staff.producer>0)state.signals.push('Tu equipo nota que la caja sigue en rojo y empieza a inquietarse por la continuidad del proyecto.');if(state.viewers<before)state.signals.push('La deuda está afectando incluso el rendimiento del canal.');}
  function accountantInfo(){return accountantCatalog[state.staff.accountant||0]}
  function accountantChance(){const info=accountantInfo();if(!info.baseChance)return 0;return clamp(info.baseChance+state.accounting.chanceBonus,0,.80)}
  function accountantTheftPct(){const info=accountantInfo();return clamp(info.baseTheft+state.accounting.theftPctBonus,0,.90)}
  function processAccountantTheft(income){state.accounting.stolenThisQuarter=0;state.accounting.lastTheft=false;const lvl=state.staff.accountant||0;if(!lvl||lvl>=3||income<=0)return 0;if(random()<accountantChance()){const amount=Math.max(1,Math.round(income*accountantTheftPct()));state.accounting.stolenThisQuarter=amount;state.accounting.lastTheft=true;state.metrics.accountantThefts++;return amount;}return 0;}
  function auditAccountant(){if(!state.staff.accountant||state.staff.accountant>=3||state.accounting.auditedTurn===state.turn)return;state.accounting.auditedTurn=state.turn;if(state.accounting.lastTheft&&state.accounting.stolenThisQuarter>0){state.staff.accountant=Math.min(3,state.staff.accountant+1);state.accounting.chanceBonus=0;state.accounting.theftPctBonus=0;state.accounting.lastTheft=false;state.accounting.stolenThisQuarter=0;state.metrics.accountantUpgrades++;state.signals.push(`La auditoría encontró dinero faltante. El contador se apenó, se disculpó y con lo que había tomado te dejó contratado gratis el siguiente nivel: ${accountantInfo().name}.`);}else{state.accounting.chanceBonus+=.02;state.accounting.theftPctBonus+=.10;state.metrics.falseAudits++;state.signals.push('Auditaste y no encontraste nada. La relación quedó peor: aumentó un poco la posibilidad de que el contador robe en el futuro y también cuánto podría llevarse.');}}
  function blockingIncident(){const powerMods=[1,.70,.44,.25,.12,.05],netMods=[1,.68,.42,.23,.11,.045];let pr=(state.location.powerRisk*powerMods[state.upgrades.power])||0,nr=(state.location.netRisk*netMods[state.upgrades.internet])||0;if(state.networkRecurring&&state.upgrades.internet<2)nr*=2.2;const roll=random();if(roll<pr)return'power';if(roll<pr+nr)return'internet';return null;}
  function moneyRequestAvailable(){return state.turn>=state.moneyRequestCooldownUntilTurn}
  function startMoneyRequestCooldown(){state.moneyRequestCooldownUntilTurn=Math.max(state.moneyRequestCooldownUntilTurn,state.turn+5)}
  function qtePool(){return qtes.filter(q=>{if((q.title||'').includes('XXXCREADORXXX')&&state.viewers<26)return false;if(state.year<3&&/patrocinador|sponsor|campaña/i.test(`${q.title||''} ${q.context||''}`))return false;if(q.dynamicBorrow&&(!moneyRequestAvailable()||state.money<100))return false;return true;});}
  function pickQTE(){const pool=qtePool();if(!pool.length)return null;return weightedPick(pool,pool.map(q=>q.dynamicBorrow?(state.location?.group==='Venezuela'?.45:.35):1));}
  function materializeQTE(q){const name=(q.title||'').includes('XXXCREADORXXX')?pickCreator():null;if(q.dynamicBorrow){const amount=Math.max(100,Math.min(1500,Math.round(Math.max(100,state.money*.18)/50)*50));const half=Math.max(50,Math.round(amount/2/50)*50);return{...q,creatorName:name,title:personalizeCreatorText(q.title,name),options:[{...O(`Prestarle ${usd.format(amount)}`,'Decides confiar. Lo que ocurra con el dinero será aleatorio.',2,0,{cost:amount}),borrowAmount:amount},{...O(`Prestarle ${usd.format(half)}`,'Ayudas, pero limitas cuánto estás dispuesto a arriesgar.',2,0,{cost:half}),borrowAmount:half},O('Decirle que no','Proteges la caja. La situación queda ahí.',1,0,{qteNeutral:true})]};}return{...q,creatorName:name,title:personalizeCreatorText(q.title,name),context:personalizeCreatorText(q.context,name)};}
