  function startNewGame({clearSave=true}={}){if(qteTimer)clearInterval(qteTimer);pendingGameOverSound=false;stopAudioChannel('ending');stopSceneSound();stopVodkaLoop();restoreVodkaNode(document.body);document.body.classList.remove('disclaimer-mode');if(clearSave)clearSavedGame();state=freshState();document.title='StreamHUB — Beta Abierta BA v0.91';topMeta.classList.add('hidden');renderIntro()}
