    const input=$('#channelName'),btn=$('#startBtn'),help=$('#channelNameHelp');const validate=()=>{const ok=input.value.trim().length>=4;btn.disabled=!ok;help.classList.toggle('error',input.value.length>0&&!ok);};input.addEventListener('input',validate);input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!btn.disabled)btn.click()});btn.addEventListener('click',()=>{const value=input.value.trim();if(value.length<4)return;state.channelName=value;renderDisclaimer()});
