  function renderQTE(raw){
    if(qteTimer)clearInterval(qteTimer);let q=materializeQTE(raw);if(/patrocinador|sponsor|campaña/i.test(`${q.title||''} ${q.context||''}`)){const brand=pickBrand(state.viewers>=8000&&random()<.5);q={...q,title:q.title.replace(/El patrocinador/g,brand).replace(/Un patrocinador/g,brand),context:q.context.replace(/El patrocinador/g,brand).replace(/la marca/g,brand)}}q={...q,options:(q.options||[]).filter(o=>!o.requiresStaff||state.staff[o.requiresStaff]>0)};if(q.dynamicBorrow)startMoneyRequestCooldown();if(q.creatorName&&!state.cameos.includes(q.creatorName))state.cameos.push(q.creatorName);const qteDuration=window.matchMedia('(max-width: 820px)').matches?5:3;let remaining=qteDuration;playSound('qte');
    screen.innerHTML=`${hudHTML()}${progressHTML()}<div class="panel-row"><section class="decision-card"><span class="tag danger">Quick-time event</span><div class="qte-clock" id="qteClock">${qteDuration.toFixed(1)}</div><h2>${q.title}</h2><p class="context">${q.context}</p><div class="qte-timer"><span id="qteBar"></span></div><div class="options">${q.options.map((o,i)=>optionButton(o,i,'qte')).join('')}</div></section>${sideHTML(false)}</div>`;
    let done=false;const complete=(idx,timed)=>{if(done)return;done=true;clearInterval(qteTimer);qteTimer=null;stopSceneSound('qte');const before=qteSnapshot();if(timed){state.metrics.qteFails++;applyOption({text:'Te quedaste congelado',energy:0,growth:-randInt(30,45),community:-3,morale:-5,risk:1});const note='Tardaste demasiado en reaccionar y el momento te golpeó fuerte.';state.signals.push(note);playSound('bad');return renderQTEResult(q,'No reaccionaste a tiempo',before,note)}let o=q.options[idx];if(!optionAllowed(o))o=q.options.find(optionAllowed)||{text:'No pudiste ejecutar tu primera opción',energy:0,growth:-35,morale:-2};
      if(o.borrowAmount){const amount=o.borrowAmount;applyOption({...o,growth:0});const roll=random();let note;if(roll<.34){state.money+=Math.round(amount*1.15);applyGrowth(randInt(10,15));state.community=clamp(state.community+2,0,100);state.metrics.qteWins++;note=`${q.creatorName} te devolvió el dinero y añadió un 15% más como agradecimiento.`;playSound('good');}else if(roll<.67){state.money+=amount;note=`${q.creatorName} te devolvió exactamente lo prestado. No pasó nada más.`;}else{applyGrowth(-randInt(30,45));state.hidden.reputation-=2;state.metrics.qteFails++;note=`${q.creatorName} no devolvió el dinero, te funó y perdiste un sponsor. Lo del sponsor queda como consecuencia narrativa, pero la funa sí golpeó fuerte tu media.`;playSound('funa');}state.signals.push(note);return renderQTEResult(q,o.text,before,note)}
      const risk=o.risk||0,original=o.growth||0;let profile='neutral';if(risk>=1)profile='bad';else if(original>=6)profile='good';const tuned={...o};if(profile==='good'){tuned.growth=randInt(10,15);state.metrics.qteWins++;playSound('good');}else if(profile==='bad'){tuned.growth=-randInt(30,45);state.metrics.qteFails++;playSound('bad');}else tuned.growth=clamp(original,-2,3);applyOption(tuned);const note='Tomaste una decisión bajo presión.';state.signals.push(note);renderQTEResult(q,o.text,before,note);};
    document.querySelectorAll('[data-qte]').forEach(b=>b.addEventListener('click',()=>complete(Number(b.dataset.qte),false)));qteTimer=setInterval(()=>{remaining-=.1;const c=$('#qteClock'),bar=$('#qteBar');if(c)c.textContent=Math.max(0,remaining).toFixed(1);if(bar)bar.style.width=`${Math.max(0,remaining/qteDuration*100)}%`;if(remaining<=0)complete(0,true)},100);bindManagementButtons('quarter');
  }
  function qteSnapshot(){return{viewers:state.viewers,money:state.money,energy:state.energy,community:state.community,morale:state.morale}}
  function renderQTEResult(q,choice,before,note){const delta={viewers:Math.round(state.viewers-before.viewers),money:Math.round(state.money-before.money),energy:Math.round(state.energy-before.energy),community:Math.round(state.community-before.community),morale:Math.round(state.morale-before.morale)};screen.innerHTML=`${hudHTML()}${progressHTML()}<div class="panel-row"><section class="decision-card qte-result-card"><span class="tag warn">Resultado del Quick-time</span><h2>${q.title}</h2><p class="context">${q.context}</p><div class="result-box"><span class="eyebrow">Elegiste</span><h3>${choice}</h3><p class="muted">${note}</p><div class="delta-row">${movementChip('Media',delta.viewers,'viewers')}${movementChip('Dinero',delta.money,'money')}${movementChip('Energía',delta.energy)}${movementChip('Comunidad',delta.community)}${movementChip('Streamer',delta.morale)}</div></div><button id="qteResultContinue" class="primary">Continuar al trimestre</button></section>${sideHTML(false)}</div>`;$('#qteResultContinue').addEventListener('click',()=>{stopSceneSound();finishQuarter()});}

  function runEvent(tier,eventRef=null){const idx=['small','medium','large','legendary'].indexOf(tier);const baseMult=[1.5,2.3,4.2,7.5][idx];const prestige=1+clamp(state.hidden.eventPrestige,0,50)/30;const community=communityState().event;const producer=1+state.staff.producer*.08;const rep=1+clamp(state.hidden.reputation,0,50)/70;const luck=.72+random()*.75,baseViewers=state.viewers;const expected=Math.round(Math.max(baseViewers*1.25,baseViewers*baseMult*prestige*community*producer*rep));const mean=Math.max(Math.round(baseViewers*1.2),Math.round(expected*luck));const peak=Math.max(mean+1,Math.round(mean*(1.35+random()*.9)));const retentionRate=.018+state.community/4000+state.hidden.identity/900+state.staff.editor*.004;const retained=Math.max(1,Math.round((mean-baseViewers)*retentionRate));const revenueFactor=.7+random()*.6,profit=Math.round((mean*.018+peak*.005)*revenueFactor);state.money+=profit;state.viewers+=retained;state.peakAverage=Math.max(state.peakAverage,state.viewers);const picked=eventRef&&typeof eventRef==='object'?eventRef:(!eventRef?eventPick(tier):null);const name=typeof eventRef==='string'?eventRef:(picked?.name||`Evento especial · Año ${state.year} T${state.quarter}`),baseName=picked?.base||name;if(baseName&&!state.usedEventNames.includes(baseName))state.usedEventNames.push(baseName);const e={tier,name,baseName,modality:picked?.modality||null,venue:picked?.venue||null,mean,peak,expected,retained,profit,baseViewers,retentionRate,revenueFactor,year:state.year,quarter:state.quarter};state.events.push(e);queueMovement({viewers:retained,money:profit},`Evento: ${e.name}`);if(!state.bestEvent||e.peak>state.bestEvent.peak)state.bestEvent=e;state.hidden.eventPrestige+=mean>=expected?2+idx:Math.max(0,idx-1);return e}
  function runSpecialEvent(tier,name,audienceBoost=1.3){const e=runEvent(tier,name),oldRetained=e.retained,oldProfit=e.profit;e.mean=Math.max(e.mean,Math.round(e.mean*audienceBoost));e.peak=Math.max(e.peak,Math.round(e.peak*audienceBoost));e.expected=Math.round(e.expected*1.15);e.retained=Math.max(1,Math.round((e.mean-e.baseViewers)*e.retentionRate));e.profit=Math.round((e.mean*.018+e.peak*.005)*e.revenueFactor);const extraRetained=Math.max(0,e.retained-oldRetained),extraProfit=Math.max(0,e.profit-oldProfit);state.viewers+=extraRetained;state.money+=extraProfit;state.peakAverage=Math.max(state.peakAverage,state.viewers);if(extraRetained||extraProfit)queueMovement({viewers:extraRetained,money:extraProfit},'Impulso especial de Twitch');if(!state.bestEvent||e.peak>state.bestEvent.peak)state.bestEvent=e;return e;}
  function renderEventOutcome(e,continueFn){const success=e.mean>=e.expected;playSound(success?'good':'bad');screen.innerHTML=`${hudHTML()}${progressHTML()}<div class="panel-row"><section class="decision-card"><span class="tag ${success?'good':'warn'}">Resultado del evento</span><h2>${e.name}</h2><p class="context">El evento tuvo números propios. ${success?'Superó la expectativa interna.':'Superó tu stream normal, pero quedó por debajo de lo que esperaba la producción.'}</p><div class="result-stats"><div class="result-stat"><span>Media del evento</span><strong>${fmt.format(e.mean)}</strong></div><div class="result-stat"><span>Pico</span><strong>${fmt.format(e.peak)}</strong></div><div class="result-stat"><span>Esperado</span><strong>${fmt.format(e.expected)}</strong></div><div class="result-stat"><span>Retenidos</span><strong>+${fmt.format(e.retained)}</strong></div><div class="result-stat"><span>Ingresos</span><strong>+${usd.format(e.profit)}</strong></div></div><div class="button-row" style="margin-top:18px"><button id="eventContinue" class="primary">Continuar</button></div></section>${sideHTML(false)}</div>`;$('#eventContinue').addEventListener('click',continueFn)}

  function finishQuarter(){if(qteTimer){clearInterval(qteTimer);qteTimer=null}stopSceneSound();recordQuarter();postQuarterChecks()}
  function updateBurnoutRisk(){
    const severe=state.morale<=24&&state.energy<=16;
    if(severe)state.burnoutStreak++;
    else if(state.morale>=36||state.energy>=32)state.burnoutStreak=0;
    else state.burnoutStreak=Math.max(0,state.burnoutStreak-1);
    if(state.burnoutStreak===1)state.signals.push('El desgaste ya no parece un mal día: estás entrando en una zona personal peligrosa.');
    else if(state.burnoutStreak===2)state.signals.push('Llevas dos trimestres al límite. Si no recuperas energía y cabeza, tu carrera puede terminar por burnout.');
    return state.burnoutStreak>=3;
  }
  function renderBurnoutRescue(continueFn){
    if(state.burnoutRescuesRemaining<=0)return false;const name=pickCreator(state.burnoutRescuers);if(!name)return false;
    state.burnoutRescuesRemaining--;state.burnoutRescuers.push(name);state.metrics.burnoutRescues++;state.burnoutStreak=0;if(!state.cameos.includes(name))state.cameos.push(name);
    const before={energy:state.energy,morale:state.morale,community:state.community};state.energy=clamp(state.energy+26,0,100);state.morale=clamp(state.morale+30,0,100);state.community=clamp(state.community+2,0,100);state.hidden.risk=Math.max(0,state.hidden.risk-1);
    queueMovement({energy:state.energy-before.energy,morale:state.morale-before.morale,community:state.community-before.community},`Apoyo de ${name}`);
    screen.innerHTML=`${hudHTML()}${progressHTML()}<div class="panel-row"><section class="decision-card catastrophe-card"><span class="tag warn">Punto de quiebre</span><h2>Tu carrera estuvo a punto de terminar.</h2><p class="context">Llevabas demasiado tiempo al límite y ya estabas listo para dejarlo. <strong>${name}</strong> habló contigo, te ayudó a ordenar la cabeza y te motivó a seguir un poco más.</p><div class="warning-box">Puedes continuar. La próxima vez no será igual.</div><button id="burnoutRescueContinue" class="primary">Seguir adelante</button></section>${sideHTML(false)}</div>`;
    $('#burnoutRescueContinue').addEventListener('click',continueFn);return true;
  }
  function postQuarterChecks(){
    if(state.money<0){state.negativeQuarters++;if(state.negativeQuarters>=3)return endCareer('Mantuviste dinero negativo durante tres trimestres del mismo año. La deuda terminó ahogando el proyecto y la carrera acabó en bancarrota.')}
    if(updateBurnoutRisk()){if(renderBurnoutRescue(continuePostQuarterChecks))return;return endCareer('El agotamiento grave y sostenido terminó por obligarte a abandonar la carrera.');}
    return continuePostQuarterChecks();
  }
  function continuePostQuarterChecks(){
    if(state.viewers<12&&state.year>=5&&state.community<38&&random()<.16)return endCareer('Tras años sin encontrar una audiencia sostenible, el canal terminó apagándose.');
    if(state.viewers>=100&&!state.credit.unlocked){state.credit.unlocked=true;state.credit.noticeShown=true;return renderCreditUnlocked(continuePostQuarterChecks);}
    if(state.money<0&&canTakeCredit())return renderNegativeBalanceChoice(continuePostQuarterChecks);
    if(state.money<-1200&&state.jobStatus==='none'&&state.viewers<3000)return endCareer('Sin trabajo y con deudas crecientes, el canal dejó de ser sostenible.');
    if(state.jobRisk>=5&&state.jobStatus!=='none'){const before=jobLabel();state.jobStatus='none';state.jobRisk=0;state.metrics.jobLosses++;queueMovement({situation:jobLabel()},'Cambio laboral');state.signals.push(`Perdiste el trabajo (${before}). Desde ahora el stream debe cubrir también tus gastos de vida.`);}
    if(state.viewers>=500&&!state.jobOfferShown&&state.jobStatus!=='none'){state.jobOfferShown=true;return renderJobDecision();}
    if(state.quarter===4)return renderYearSummary();advanceQuarter();
  }

  function recordQuarter(){state.history.push({year:state.year,quarter:state.quarter,viewers:Math.round(state.viewers),money:Math.round(state.money),energy:Math.round(state.energy),community:state.community,morale:state.morale,income:Math.round(state.ledger?.income||0)});state.turn++;state.currentDecision=null;state.quarterStarted=false;state.visibleMovements=[]}
  function advanceQuarter(){state.quarter++;if(state.quarter>4){state.quarter=1;state.year++}if(state.turn>=state.maxTurns||state.year>15)return endCareer('Completaste quince años de carrera.');renderQuarter()}
  function renderJobDecision(){const opts=[{id:'quit',title:'Renunciar ahora',desc:'Ganas tiempo y energía. Desde el próximo trimestre el stream debe pagar también tus gastos de vida.'},{id:'part',title:'Pasar a medio tiempo',desc:'Menos ahorro laboral, pero recuperas parte de la energía.'},{id:'stay',title:'Mantener el trabajo',desc:'El dinero extra sigue siendo simbólico; el verdadero costo es el desgaste.'}];screen.innerHTML=`${hudHTML()}${progressHTML()}<section class="decision-card"><span class="tag good">Hito de carrera</span><h2>Superaste 500 viewers de media.</h2><p class="context">Ya puedes dejar el trabajo. No significa que sea financieramente seguro: si renuncias, también aparecen los gastos de vida que hoy cubre tu sueldo.</p><div class="options">${opts.map(o=>`<button class="option-btn" data-job="${o.id}"><span class="option-copy"><strong>${o.title}</strong><small>${o.desc}</small></span></button>`).join('')}</div></section>`;document.querySelectorAll('[data-job]').forEach(b=>b.addEventListener('click',()=>{const before=jobLabel();if(b.dataset.job==='quit'){state.jobStatus='none';state.energy=clamp(state.energy+8,0,100);state.morale=clamp(state.morale+4,0,100)}else if(b.dataset.job==='part'){state.jobStatus='part';state.energy=clamp(state.energy+4,0,100)}if(jobLabel()!==before)queueMovement({situation:jobLabel()},'Decisión laboral');advanceAfterRecordedQuarter()}))}
  function advanceAfterRecordedQuarter(){if(state.quarter===4)return renderYearSummary();advanceQuarter()}

  function renderYearSummary(){const year=state.year;const rows=state.history.filter(h=>h.year===year);const avg=rows.length?Math.round(rows.reduce((sum,h)=>sum+h.viewers,0)/rows.length):Math.round(state.viewers);if(state.yearlyAverages.length<year)state.yearlyAverages.push(avg);const annualPayment=processAnnualCreditPayment(year);const all=state.yearlyAverages,max=Math.max(...all,1);screen.innerHTML=`${hudHTML()}<section class="year-summary"><span class="tag good">Resumen anual</span><div class="year-number">AÑO ${year}</div><h2>${yearHeadline(avg)}</h2><p class="lead">Media del año: <strong>${fmt.format(avg)} viewers</strong>.</p>${annualPayment?`<div class="warning-box">Pago anual del crédito: <strong>−${usd.format(annualPayment)}</strong>. Saldo pendiente: ${usd.format(Math.round(state.credit.balance))}.</div>`:''}<div class="card trajectory-card"><div class="mini-bars">${all.map((v,i)=>`<div class="bar-column"><div class="bar-value">${shortNum(v)}</div><div class="bar-fill" style="height:${Math.max(8,v/max*100)}%"></div><div class="bar-label">${i+1} · ${shortNum(v)}</div></div>`).join('')}</div></div><div class="button-row">${year<15?`<button id="nextYear" class="primary">Comenzar año ${year+1}</button>`:''}${year>=5?'<button id="retireBtn" class="ghost">Retirarme ahora</button>':''}</div></section>`;$('#nextYear')?.addEventListener('click',()=>advanceQuarter());$('#retireBtn')?.addEventListener('click',()=>endCareer(`Decidiste retirarte voluntariamente al terminar el año ${year}.`));if(year>=15)setTimeout(()=>endCareer('Completaste quince años de carrera.'),50)}
  function yearHeadline(avg){if(avg<10)return'Todavía estás hablando para casi nadie.';if(avg<100)return'Ya existe una pequeña comunidad.';if(avg<500)return'El canal empieza a sentirse posible.';if(avg<2000)return'El streaming ya compite con tu vida anterior.';if(avg<5000)return'Tu nombre ya pesa dentro de la comunidad.';if(avg<15000)return'Ya eres una figura grande.';if(avg<30000)return'Tu canal entra en otra liga.';if(avg<50000)return'Eres una superestrella del directo.';return'La palabra “leyenda” ya no es exageración.'}

  function renderShop(returnTo='quarter'){state.shopReturn=returnTo;const tab=state.shopTab||'upgrades';screen.innerHTML=`${hudHTML()}<section class="shop-wrap"><div><span class="eyebrow">GESTIÓN DEL CANAL</span><h2>Tienda y equipo</h2><p class="muted">Piensa bien en como usar el dinero que has ganado con tu esfuerzo.</p></div><div class="tabs"><button class="tab ${tab==='upgrades'?'active':''}" data-tab="upgrades">Mejoras</button><button class="tab ${tab==='consumables'?'active':''}" data-tab="consumables">Consumibles</button><button class="tab ${tab==='team'?'active':''}" data-tab="team">Equipo</button></div><div id="shopContent">${shopContent(tab)}</div><div class="button-row"><button id="shopBack" class="primary">Volver</button>${state.credit.unlocked?'<button id="shopCredit" class="ghost">Crédito y pagos</button>':''}</div></section>`;document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{state.shopTab=b.dataset.tab;renderShop(returnTo)}));bindShop(tab);$('#shopBack').addEventListener('click',()=>returnFromManagement(returnTo));$('#shopCredit')?.addEventListener('click',()=>renderCreditPanel(returnTo))}
  function returnFromManagement(returnTo){if(returnTo&&typeof returnTo==='object'&&returnTo.kind==='decisionResult')return renderDecisionResult(returnTo.d,returnTo.o,returnTo.delta);renderQuarter()}
  function renderCreditUnlocked(returnFn){const lender=creditLender();playSound('creditNotice');screen.innerHTML=`${hudHTML()}${progressHTML()}<section class="decision-card"><span class="tag warn">Nueva herramienta financiera</span><h2>Ahora puedes solicitar un crédito.</h2><p class="context">Como ahora eres "famosito", ${lender} está dispuesto a financiar tu canal. Normalmente puedes pedir hasta <strong>$10.000</strong>. Si tienes deudas, el crédito únicamente cubrirá la deuda y dejará <strong>$1.000</strong> disponibles. Nada en esta vida es gratis: <strong>hay 35% de interés</strong> y tres pagos anuales. Solo tienes <strong>dos créditos</strong>; además existe como máximo <strong>un salvavidas de deuda</strong> si tu caja cae en negativo.</p><div class="warning-box">Un crédito puede salvar una crisis o acelerar una inversión, pero sus cuotas son rígidas y pueden terminar una carrera que todavía no produce suficiente dinero.</div><div class="button-row"><button id="creditNoticeContinue" class="primary">Entendido</button><button id="creditNoticeOpen" class="ghost">Ver panel de crédito</button></div></section>`;$('#creditNoticeContinue').addEventListener('click',returnFn);$('#creditNoticeOpen').addEventListener('click',()=>renderCreditPanel({kind:'callback',fn:returnFn}))}

  function renderNegativeBalanceChoice(returnFn){const debt=Math.abs(Math.round(state.money)),principal=debt+1000,total=Math.round(principal*1.35);screen.innerHTML=`${hudHTML()}${progressHTML()}<section class="decision-card"><span class="tag danger">Caja negativa</span><h2>El canal quedó en números rojos.</h2><p class="context">Debes ${usd.format(debt)}. ${creditLender()} solo te ofrece una salida de emergencia: cubrir la deuda y dejar exactamente $1.000 en caja. El principal será ${usd.format(principal)} y terminarás devolviendo aproximadamente ${usd.format(total)}.</p><div class="options"><button id="takeEmergencyCredit" class="option-btn"><span class="option-copy"><strong>Aceptar el crédito</strong><small>Sales de la deuda inmediata, pero asumes 35% de interés y tres pagos anuales.</small></span></button><button id="endForDebt" class="option-btn danger-option"><span class="option-copy"><strong>Finalizar la carrera</strong><small>No quieres asumir una deuda de este tamaño.</small></span></button></div></section>`;$('#takeEmergencyCredit').addEventListener('click',()=>{takeCredit();returnFn()});$('#endForDebt').addEventListener('click',()=>endCareer('Decidiste cerrar el canal antes de asumir un crédito para cubrir la deuda.'))}

  function renderCreditPanel(returnTo='quarter'){
    const c=state.credit,lender=creditLender();const debt=Math.max(0,-Math.round(state.money));const emergency=returnTo&&typeof returnTo==='object'&&returnTo.kind==='pcEmergency';
    const defaultAmount=1000;const fixedPrincipal=debt+1000;
    screen.innerHTML=`${hudHTML()}<section class="shop-wrap"><div><span class="eyebrow">FINANZAS</span><h2>${emergency?'Crédito de emergencia':'Crédito y pagos'}</h2><p class="muted">${lender} · interés fijo del 35% · tres pagos anuales. Usos: ${c.voluntaryCount}/2 voluntarios · ${c.emergencyCount}/1 salvavidas de deuda.</p></div>${c.active?`<div class="credit-grid"><div class="shop-card"><span class="tag warn">Crédito activo</span><h3>${usd.format(Math.round(c.balance))} pendientes</h3><p class="muted small">Principal original: ${usd.format(c.principal)}. Próximo pago anual: ${usd.format(Math.min(c.annualPayment,c.balance))} al cerrar el año ${c.nextDueYear}.</p><div class="credit-meter"><span style="width:${Math.max(0,Math.min(100,(1-c.balance/(c.principal*1.35))*100))}%"></span></div></div><div class="shop-card"><span class="tag">Abonos anticipados</span><h3>Reducir la deuda</h3><p class="muted small">Los abonos salen de tu caja actual y reducen el saldo.</p><div class="button-row"><button class="secondary" data-credit-pay="250" ${state.money<250?'disabled':''}>Pagar $250</button><button class="secondary" data-credit-pay="500" ${state.money<500?'disabled':''}>Pagar $500</button><button class="ghost" data-credit-pay="all" ${state.money<=0?'disabled':''}>Pagar todo lo posible</button></div></div></div>`:`<div class="shop-card"><span class="tag good">Disponible</span><h3>Solicitar crédito</h3>${debt?`<p class="muted small">Estás en negativo. No puedes elegir monto: el crédito cubrirá ${usd.format(debt)} y dejará $1.000 disponibles. Principal: <strong>${usd.format(fixedPrincipal)}</strong>; deuda con interés: <strong>${usd.format(Math.round(fixedPrincipal*1.35))}</strong>.</p><button id="takeCreditBtn" class="secondary" ${canTakeCredit()?'':'disabled'}>Solicitar ${usd.format(fixedPrincipal)}</button>`:`<p class="muted small">Sin deudas puedes elegir cuánto financiar hasta $10.000. Cuanto mayor sea el monto, mayores serán las tres cuotas anuales.</p><div class="credit-amount-row"><label for="creditAmount">Monto</label><input id="creditAmount" type="number" min="1000" max="10000" step="100" value="${defaultAmount}"><div id="creditQuote" class="credit-quote"></div></div><button id="takeCreditBtn" class="secondary" ${canTakeCredit()?'':'disabled'}>Solicitar crédito</button>`}</div>`}<div class="card"><h3>Riesgo</h3><p class="muted small">La cuota no se adapta a tu audiencia. Pedir $10.000 no mejora el canal por sí mismo y puede convertir una mala inversión en el final de la carrera.</p></div><div class="button-row">${emergency?'':'<button id="creditBack" class="primary">Volver</button>'}</div></section>`;
    const input=$('#creditAmount'),quote=$('#creditQuote');const updateQuote=()=>{if(!input||!quote)return;const amount=clamp(Math.round(Number(input.value)||1000),1000,10000);const total=Math.round(amount*1.35);quote.textContent=`Recibes ${usd.format(amount)} · devuelves aprox. ${usd.format(total)} · ${usd.format(Math.ceil(total/3))}/año`;};input?.addEventListener('input',updateQuote);updateQuote();
    $('#takeCreditBtn')?.addEventListener('click',()=>{const amount=debt?null:clamp(Math.round(Number(input?.value)||1000),1000,10000);if(!takeCredit(amount))return;if(emergency)return renderRecoverySetupChoice('credit');renderCreditPanel(returnTo)});
    document.querySelectorAll('[data-credit-pay]').forEach(b=>b.addEventListener('click',()=>{const raw=b.dataset.creditPay;const amount=raw==='all'?Math.min(state.money,state.credit.balance):Number(raw);payCredit(amount,false);renderCreditPanel(returnTo)}));
    $('#creditBack')?.addEventListener('click',()=>{if(returnTo&&typeof returnTo==='object'&&returnTo.kind==='callback')return returnTo.fn();returnFromManagement(returnTo)});
  }


  function consumableLimitStatus(id,maxPerYear,cooldownTurns){
    const u=state.consumableUsage[id];if(!u)return{ok:true};if(u.year!==state.year)return{ok:true};if(u.count>=maxPerYear)return{ok:false,reason:`Límite ${maxPerYear} por año`};if(state.turn-u.lastTurn<cooldownTurns)return{ok:false,reason:'Necesita enfriamiento'};return{ok:true};
  }
  function markConsumableUse(id){const u=state.consumableUsage[id];if(!u)return;if(u.year!==state.year){u.year=state.year;u.count=0;}u.count++;u.lastTurn=state.turn;}

  function shopContent(tab){if(tab==='upgrades')return`<div class="shop-grid">${Object.entries(upgradeCatalog).map(([id,u])=>upgradeCard(id,u)).join('')}</div>`;if(tab==='consumables')return`<div class="shop-grid">${consumables.map(c=>consumableCard(c)).join('')}</div>`;return teamShop()}
  function upgradeCard(id,u){const lvl=state.upgrades[id],max=lvl>=5,next=max?null:u.costs[lvl+1];return`<div class="shop-card"><span class="tag ${max?'good':''}">${max?'Máximo':`Nivel ${lvl}/5`}</span><h3>${u.name}</h3><p class="muted small">${u.desc}</p><div class="shop-levels">${[1,2,3,4,5].map(n=>`<span class="level-dot ${n<=lvl?'on':''}"></span>`).join('')}</div><div class="price-line"><span>${max?'Mejora completada':`Siguiente: ${usd.format(next)}`}</span>${max?'<span class="bought">COMPRADO</span>':`<button class="secondary" data-upgrade="${id}" ${state.money<next?'disabled':''}>Mejorar</button>`}</div></div>`}
  function consumableCost(c){return Math.round(c.baseCost)}
  function consumableCard(c){const cost=consumableCost(c);const status=c.can?c.can():{ok:true};return`<div class="shop-card ${status.ok?'':'disabled'}"><span class="tag warn">Consumible</span><h3>${c.name}</h3><p class="muted small">${c.desc}</p><div class="price-line"><span>${status.ok?usd.format(cost):status.reason}</span><button class="secondary" data-consumable="${c.id}" ${state.money<cost||!status.ok?'disabled':''}>Usar</button></div></div>`}

  function teamShop(){const s=state.staff;const modNames=s.modNames||[];const mod=staffCatalog.mod,modNext=s.mod+1,modMax=s.mod>=5,modMin=modMax?0:mod.mins[modNext],modLocked=state.viewers<modMin;const modCard=`<div class="shop-card ${modLocked&&s.mod===0?'disabled':''}"><span class="tag ${modMax?'good':''}">${modMax?'Equipo completo':`${s.mod}/5 moderadores`}</span><h3>Moderación</h3><p class="muted small">Cada contratación es una persona dentro de tu carrera.</p>${modNames.length?`<div class="named-team-list">${modNames.map((n,i)=>`<div><span>${n}</span><button class="danger-btn compact-btn" data-fire-mod="${i}">Despedir</button></div>`).join('')}</div>`:'<p class="tiny muted">Todavía no has contratado moderadores.</p>'}${state.pendingModerator?`<div class="inline-hire"><label for="moderatorName">¿Cómo se llama tu moderador?</label><input id="moderatorName" maxlength="24" placeholder="Nombre del moderador" autocomplete="off" /><div class="button-row"><button id="confirmModerator" class="secondary">Confirmar contratación</button><button id="cancelModerator" class="ghost">Cancelar</button></div></div>`:''}<div class="team-meta"><span>Costo trimestral actual: ${usd.format(mod.costs[s.mod])}</span>${!modMax?`<span>Siguiente: ${usd.format(mod.costs[modNext])}/trim.</span>`:''}</div><button class="secondary" id="hireModerator" ${modMax||modLocked||state.pendingModerator?'disabled':''}>${modMax?'Moderación completa':modLocked?`Siguiente moderador desde ${fmt.format(modMin)} viewers`:'Contratar moderador'}</button></div>`;
    const editor=staffCatalog.editor,editorLvl=s.editor,editorMax=editorLvl>=5,editorNext=editorMax?null:editor.costs[editorLvl+1],editorMin=editorMax?0:editor.mins[editorLvl+1],editorLocked=state.viewers<editorMin;const editorCard=`<div class="shop-card ${editorLocked&&editorLvl===0?'disabled':''}"><span class="tag ${editorMax?'good':''}">${editorMax?'Editor máximo':`Nivel ${editorLvl}/5`}</span><h3>${s.editorName?`${s.editorName} · Editor de clips`:'Editor de clips'}</h3><p class="muted small">Un solo editor al que le vas entregando mejores herramientas de trabajo.</p><div class="shop-levels">${[1,2,3,4,5].map(n=>`<span class="level-dot ${n<=editorLvl?'on':''}"></span>`).join('')}</div>${state.pendingEditor?`<div class="inline-hire"><label for="editorName">¿Cómo se llama tu editor?</label><input id="editorName" maxlength="24" placeholder="Nombre del editor" autocomplete="off" /><div class="button-row"><button id="confirmEditor" class="secondary">Confirmar contratación</button><button id="cancelEditor" class="ghost">Cancelar</button></div></div>`:''}<div class="team-meta"><span>Costo trimestral actual: ${usd.format(editor.costs[editorLvl])}</span>${!editorMax?`<span>Siguiente: ${usd.format(editorNext)}/trim.</span>`:''}</div><div class="button-row"><button class="secondary" id="upgradeEditor" ${editorMax||editorLocked||state.pendingEditor?'disabled':''}>${editorMax?'Editor al máximo':editorLocked?`Requiere ${fmt.format(editorMin)} viewers`:editorLvl===0?'Contratar editor':'Subir nivel'}</button>${editorLvl>0?`<button class="danger-btn" id="fireEditor">Despedir editor</button>`:''}</div></div>`;
    const c=staffCatalog.producer,lvl=s.producer,max=lvl>=5,next=max?null:c.costs[lvl+1],min=max?0:c.mins[lvl+1],locked=state.viewers<min;const producerCard=`<div class="shop-card ${locked&&lvl===0?'disabled':''}"><span class="tag ${max?'good':''}">${max?'Equipo completo':`Nivel ${lvl}/5`}</span><h3>${c.name}</h3><p class="muted small">${c.desc}</p><div class="shop-levels">${[1,2,3,4,5].map(n=>`<span class="level-dot ${n<=lvl?'on':''}"></span>`).join('')}</div><div class="team-meta"><span>Costo trimestral actual: ${usd.format(c.costs[lvl])}</span>${!max?`<span>Siguiente: ${usd.format(next)}/trim.</span>`:''}</div><div class="button-row"><button class="secondary" data-staff="producer" ${max||locked?'disabled':''}>${max?'Contratado al máximo':locked?`Requiere ${fmt.format(min)} viewers`:'Subir nivel'}</button>${lvl>0?`<button class="danger-btn" data-fire="producer">Despedir equipo</button>`:''}</div></div>`;const roleCards=editorCard+producerCard;
    const rep=representation[s.representation],acc=accountantInfo();const nextAcc=Math.min(3,(s.accountant||0)+1);const accCard=`<div class="shop-card"><span class="tag ${s.accountant>=3?'good':'warn'}">Contabilidad ${s.accountant}/3</span><h3>${acc.name}</h3><p class="muted small">${acc.desc}</p><div class="team-meta"><span>Costo actual: ${usd.format(acc.cost)}/trim.</span>${s.accountant<3?`<span>Siguiente: ${accountantCatalog[nextAcc].name}</span>`:''}</div>${s.accountant<3?`<button class="secondary" data-accountant="${nextAcc}">${s.accountant===0?'Contratar':'Mejorar'} · ${usd.format(accountantCatalog[nextAcc].cost)}/trim.</button>`:'<span class="bought">FINANZAS PROFESIONALES</span>'}${s.accountant>0?'<div class="spacer"></div><button class="danger-btn" data-accountant="0">Dejar de tener contador</button>':''}</div>`;
    return`<div class="shop-grid">${modCard}${roleCards}<div class="shop-card"><span class="tag">Representación</span><h3>${rep.name}</h3><p class="muted small">${rep.desc}</p><div class="team-meta"><span>Costo actual: ${usd.format(rep.cost)}/trim.</span></div>${s.representation==='none'?`<button class="secondary" data-rep="manager" ${state.viewers<representation.manager.min?'disabled':''}>${state.viewers<representation.manager.min?`Mánager desde ${representation.manager.min} viewers`:`Contratar mánager · ${usd.format(representation.manager.cost)}/trim.`}</button>`:s.representation==='manager'?`<button class="secondary" data-rep="agency" ${state.viewers<representation.agency.min?'disabled':''}>${state.viewers<representation.agency.min?`Agencia desde ${fmt.format(representation.agency.min)} viewers`:`Pasar a agencia · ${usd.format(representation.agency.cost)}/trim.`}</button><div class="spacer"></div><button class="danger-btn" data-rep="none">Dejar de tener representación</button>`:`<span class="bought">Agencia contratada</span><div class="spacer"></div><button class="ghost" data-rep="manager">Volver a mánager</button><button class="danger-btn" data-rep="none">Dejar de tener representación</button>`}</div>${accCard}</div>`}
  function bindShop(tab){document.querySelectorAll('#moderatorName,#editorName').forEach(input=>input.addEventListener('input',()=>{input.value=sanitizeTeamName(input.value)}));
    if(tab==='upgrades')document.querySelectorAll('[data-upgrade]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.upgrade,lvl=state.upgrades[id],cost=upgradeCatalog[id].costs[lvl+1];if(state.money<cost||lvl>=5)return;state.money-=cost;state.upgrades[id]++;if(id==='internet'&&state.upgrades.internet>=2)state.networkRecurring=false;if(id==='audio')state.community=clamp(state.community+1,0,100);renderShop(state.shopReturn)}));
    if(tab==='consumables')document.querySelectorAll('[data-consumable]').forEach(b=>b.addEventListener('click',()=>{const c=consumables.find(x=>x.id===b.dataset.consumable),cost=consumableCost(c),status=c.can?c.can():{ok:true};if(state.money<cost||!status.ok)return;state.money-=cost;c.use();if(state.careerEnded)return;state.energy=clamp(state.energy,0,100);state.community=clamp(state.community,0,100);state.morale=clamp(state.morale,0,100);state.metrics.minMorale=Math.min(state.metrics.minMorale,state.morale);state.metrics.minCommunity=Math.min(state.metrics.minCommunity,state.community);renderShop(state.shopReturn)}));
    if(tab==='team'){
      document.querySelectorAll('[data-staff]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.staff,c=staffCatalog[id],next=state.staff[id]+1;if(next>5||state.viewers<c.mins[next])return;state.staff[id]=next;renderShop(state.shopReturn)}));
      $('#upgradeEditor')?.addEventListener('click',()=>{const next=state.staff.editor+1;if(next>5||state.viewers<staffCatalog.editor.mins[next])return;if(state.staff.editor===0){state.pendingEditor=true;return renderShop(state.shopReturn)}state.staff.editor=next;renderShop(state.shopReturn)});$('#cancelEditor')?.addEventListener('click',()=>{state.pendingEditor=false;renderShop(state.shopReturn)});$('#confirmEditor')?.addEventListener('click',()=>{const input=$('#editorName'),name=sanitizeTeamName((input?.value||'').trim());if(name.length<2){input?.classList.add('input-error');return}state.staff.editorName=name;state.staff.editor=1;state.pendingEditor=false;state.signals.push(`${name} se incorporó como editor de clips.`);renderShop(state.shopReturn)});$('#fireEditor')?.addEventListener('click',()=>{state.staff.editor=0;state.staff.editorName='';state.pendingEditor=false;state.signals.push('Despediste a tu editor. Dejaste de pagar su costo trimestral, sin recuperar inversiones anteriores.');renderShop(state.shopReturn)});
      document.querySelectorAll('[data-fire]').forEach(b=>b.addEventListener('click',()=>{state.staff[b.dataset.fire]=0;if(b.dataset.fire==='editor')state.staff.editorName='';state.signals.push('Reduciste tu equipo para cortar gastos futuros. No recuperaste el dinero invertido.');renderShop(state.shopReturn)}));
      $('#hireModerator')?.addEventListener('click',()=>{state.pendingModerator=true;renderShop(state.shopReturn)});$('#cancelModerator')?.addEventListener('click',()=>{state.pendingModerator=false;renderShop(state.shopReturn)});$('#confirmModerator')?.addEventListener('click',()=>{const input=$('#moderatorName'),name=sanitizeTeamName((input?.value||'').trim());const next=state.staff.mod+1;if(name.length<2){input?.classList.add('input-error');return}if(next>5||state.viewers<staffCatalog.mod.mins[next])return;state.staff.modNames.push(name);state.staff.mod=state.staff.modNames.length;state.pendingModerator=false;state.signals.push(`${name} se incorporó al equipo de moderación.`);renderShop(state.shopReturn)});
      document.querySelectorAll('[data-fire-mod]').forEach(b=>b.addEventListener('click',()=>{const idx=Number(b.dataset.fireMod),name=state.staff.modNames[idx];state.staff.modNames.splice(idx,1);state.staff.mod=state.staff.modNames.length;state.signals.push(`${name} dejó el equipo de moderación. No recuperaste gastos anteriores.`);renderShop(state.shopReturn)}));
      document.querySelectorAll('[data-rep]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.rep;if(id!=='none'&&state.viewers<representation[id].min)return;state.staff.representation=id;renderShop(state.shopReturn)}));
      document.querySelectorAll('[data-accountant]').forEach(b=>b.addEventListener('click',()=>{state.staff.accountant=Number(b.dataset.accountant);if(state.staff.accountant===0){state.accounting.chanceBonus=0;state.accounting.theftPctBonus=0;state.accounting.lastTheft=false;state.accounting.stolenThisQuarter=0;}state.signals.push(state.staff.accountant?`Ahora tus finanzas las lleva: ${accountantInfo().name}.`:'Decidiste quedarte sin contador.');renderShop(state.shopReturn)}));
    }
  }
