    if(!state.credit.everTaken&&years>=8)b.push('Sin deuda bancaria');
    if(state.credit.largest>=7500)b.push('Apuesta de cinco cifras');
    if(state.metrics.clipSprintWins>=3)b.push('Disciplina de clips');
    if(years>=15)b.push('Quince años en vivo');
    if(state.location.group==='Venezuela'&&state.hidden.international>=12)b.push('De Venezuela para el mundo');
    if(state.location.group==='Migrante'&&state.hidden.international>=12)b.push('Puente de la Migrante');
    if(maxMoney>18000)b.push('Caja fuerte');
    if(state.metrics.kickMoves>0)b.push('Mudanza a KICK');
    if(state.metrics.twitchReturns>0)b.push('Regreso a Twitch');
    if((state.staff.modNames||[]).length>=3)b.push('Moderación con nombres');
    if(state.metrics.accountantUpgrades>0)b.push('Contador ascendido');
    if(state.metrics.taxEvents>0&&!state.endReason.includes('bancarrota'))b.push('Sobrevivió a la multa');
    if(state.staff.accountant>=3)b.push('Finanzas profesionales');
