  function drawIsoBackdrop(ctx,img,W,H){
    if(!img||!img.complete||!img.naturalWidth||!img.naturalHeight)return false;
    const ratio=img.naturalWidth/img.naturalHeight;
    let fullH=Math.round(H*.805);
    let fullW=Math.max(2,Math.round(fullH*ratio));
    let visibleW=Math.max(1,Math.round(fullW*.50));
    const maxVisibleW=Math.round(W*.98);
    if(visibleW>maxVisibleW){
      const fit=maxVisibleW/visibleW;
      fullW=Math.max(2,Math.round(fullW*fit));
      fullH=Math.max(2,Math.round(fullH*fit));
      visibleW=Math.max(1,Math.round(fullW*.50));
    }

    const full=document.createElement('canvas');
    full.width=fullW;full.height=fullH;
    const f=full.getContext('2d');
    f.clearRect(0,0,fullW,fullH);
    f.drawImage(img,0,0,fullW,fullH);

    const cropped=document.createElement('canvas');
    cropped.width=visibleW;cropped.height=fullH;
    const c=cropped.getContext('2d');
    c.clearRect(0,0,visibleW,fullH);
    c.drawImage(full,0,0,visibleW,fullH,0,0,visibleW,fullH);
    c.globalCompositeOperation='source-in';
    c.fillStyle='#b38cff';
    c.fillRect(0,0,visibleW,fullH);
    const x=W-visibleW;
    const y=Math.round((H-fullH)*.50);
    ctx.save();
    ctx.globalAlpha=.055;
    ctx.drawImage(cropped,x,y,visibleW,fullH);
    ctx.restore();
    return true;
  }
